contents.rollMessage:
%{
const maxPV = Number("${H0D_Machine_PV_Max_Calc}$");
await entity.update({"system.props.H0D_Machine_PV_Actuels": maxPV});
return "<strong>Intégrité restaurée :</strong> " + maxPV + " / " + maxPV;
}%

%{
const actor = entity.entity ? entity.entity : entity;
const bonus = Number("${H0D_Machine_Initiative}$") || 0;
const roll = await (new foundry.dice.Roll("1d20 + (" + bonus + ")")).evaluate();
const natural = Number(roll.total || 0) - bonus;
let trackerStatus = "Combat Tracker non mis à jour";
try {
  let token = null;
  const controlled = canvas?.tokens?.controlled || [];
  token = controlled.find(t => t.actor === actor || t.document?.actorId === actor.id) || null;
  if (!token && typeof actor.getActiveTokens === "function") {
    const active = actor.getActiveTokens();
    token = active[0] || null;
  }
  const tokenDoc = token?.document || actor.token || null;
  if (!tokenDoc) throw new Error("Aucun token actif pour cet acteur.");
  let combat = game.combat || null;
  let combatant = combat?.combatants?.find(c => c.tokenId === tokenDoc.id) || null;
  if (!combatant) {
    const created = await foundry.documents.TokenDocument.createCombatants([tokenDoc], combat ? {combat} : {});
    combatant = created?.find(c => c.tokenId === tokenDoc.id) || created?.[0] || null;
    combat = combatant?.parent || game.combat || combat;
  }
  if (!combat || !combatant) throw new Error("Impossible de créer ou retrouver le combattant.");
  await combat.setInitiative(combatant.id, roll.total);
  trackerStatus = "Ajoutée au Combat Tracker";
} catch (err) {
  console.warn("H0D — initiative : Combat Tracker non mis à jour.", err);
}
return "<div class=\"h0d-chat-card h0d-chat-initiative h0d-chat-machine\">"
  + "<div class=\"h0d-chat-headline\">Initiative</div>"
  + "<table class=\"h0d-chat-summary\"><tr><td><strong>Résultat</strong></td><td><strong>" + roll.total + "</strong></td></tr></table>"
  + "<div class=\"h0d-chat-status\">" + trackerStatus + "</div>"
  + "<details><summary>Détails du jet</summary><table>"
  + "<tr><td>d20</td><td><strong>" + natural + "</strong></td></tr>"
  + "<tr><td>Bonus total</td><td><strong>" + (bonus >= 0 ? "+" : "") + bonus + "</strong></td></tr>"
  + "</table></details>"
  + "</div>";
}%

rowLayout.rollMessage:
%{
const part = linkedEntity;
if (!part) {
  if (ui.notifications) ui.notifications.warn("H0D : pièce introuvable.");
  return "";
}
if (!game.user?.isGM) {
  if (ui.notifications) ui.notifications.warn("H0D : la modification des PV de pièce est réservée au MJ.");
  return "";
}

const p = part.system?.props || {};
let currentKey = "";
let maxKey = "";

if (Object.prototype.hasOwnProperty.call(p, "H0D_Composant_PV_Actuels")) {
  currentKey = "H0D_Composant_PV_Actuels";
  maxKey = "H0D_Composant_PV_Max";
} else if (Object.prototype.hasOwnProperty.call(p, "H0D_ArmeMachine_PV_Actuels")) {
  currentKey = "H0D_ArmeMachine_PV_Actuels";
  maxKey = "H0D_ArmeMachine_PV_Max";
} else {
  if (ui.notifications) ui.notifications.warn("H0D : cette ligne ne possède pas de PV éditables.");
  return "";
}

const cur = Math.max(0, Number(p[currentKey] || 0));
const maxPv = Math.max(0, Number(p[maxKey] || 0));

const fd = await foundry.applications.api.DialogV2.input({
  window: {title: "PV — " + part.name},
  content:
    "<div class=\"form-group\"><label>PV actuels</label>"
    + "<input name=\"current\" type=\"number\" min=\"0\" step=\"1\" value=\"" + cur + "\"></div>"
    + "<div class=\"form-group\"><label>PV max</label>"
    + "<input name=\"max\" type=\"number\" min=\"0\" step=\"1\" value=\"" + maxPv + "\"></div>"
    + "<p style=\"margin-top:8px\"><em>0 PV neutralise la pièce ; détachement ou destruction selon les dégâts du coup et le seuil critique 200 %.</em></p>",
  ok: {label: "Appliquer"},
  rejectClose: false,
  modal: true
});

if (!fd) return "";

const newMax = Math.max(0, Math.floor(Number(fd.max ?? maxPv) || 0));
const newCurrent = Math.max(0, Math.min(newMax, Math.floor(Number(fd.current ?? cur) || 0)));

await part.update({
  ["system.props." + maxKey]: newMax,
  ["system.props." + currentKey]: newCurrent
});

if (ui.notifications) {
  ui.notifications.info("H0D : " + part.name + " — PV " + newCurrent + " / " + newMax);
}
return "";
}%

${#?{H0D_Attaque_Mod_Situ:'Modificateur situationnel'[number]|0}}$
${#H0D_Machine_ATK_TMP:= (or(equalText(item.H0D_ArmeMachine_Etat,'Detachee'),equalText(item.H0D_ArmeMachine_Etat,'Detruite')) ? 0 : (item.H0D_ArmeMachine_PV_Actuels > 0 ? 1 : 0)) > 0 ? H0D_Machine_Attaque_Effective_Calc + item.H0D_ArmeMachine_Bonus_Attaque + (and(H0D_Machine_Etat_Aveuglee,or(equalText(item.H0D_ArmeMachine_Mode,'Distance'),equalText(item.H0D_ArmeMachine_Mode,'Zone'))) ? -4 : 0) : 0}$
${#H0D_Machine_ATK_ROLL:=[1d20]}$
%{
try {
  const actor = entity.entity ? entity.entity : entity;
  const weapon = linkedEntity;
  if (!weapon) return "<strong>Arme / attaque introuvable.</strong>";
  const wp = weapon.system && weapon.system.props ? weapon.system.props : {};
  const mode = String(wp.H0D_ArmeMachine_Mode || "Naturelle");

  function esc(v) {
    return String(v === undefined || v === null ? "" : v)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


const h0dTargets = Array.from(game.user?.targets || []);

  function h0dNum(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  }
  function h0dBool(v) {
    return v === true || v === "true" || v === 1 || v === "1";
  }
  function h0dHas(o, k) {
    return !!o && Object.prototype.hasOwnProperty.call(o, k);
  }
  function h0dRows(v) {
    if (Array.isArray(v)) return v;
    if (v && typeof v === "object") return Object.values(v);
    return [];
  }
  function h0dTraitDef(ip, prefix) {
    const directKey = prefix + "_Trait_DEF_Total";
    if (h0dHas(ip, directKey) && ip[directKey] !== "") {
      const direct = Number(ip[directKey]);
      if (Number.isFinite(direct)) return direct;
    }
    let total = 0;
    for (const row of h0dRows(ip[prefix + "_Traits_Table"])) {
      if (!row || typeof row !== "object") continue;
      const activeKey = prefix + "_Trait_Actif";
      if (h0dHas(row, activeKey) && !h0dBool(row[activeKey])) continue;
      const effect = String(
        row[prefix + "_Trait_Effet_Actif_Calc"]
        ?? row[prefix + "_Trait_Effet"]
        ?? ""
      ).toUpperCase();
      if (effect !== "DEF") continue;
      total += h0dNum(
        row[prefix + "_Trait_Valeur_Active_Calc"]
        ?? row[prefix + "_Trait_Valeur"]
        ?? 0
      );
    }
    return total;
  }

  function h0dResolveDefense(targetActor) {
    if (!targetActor) return null;
    const p = targetActor.system?.props || {};
    const items = Array.from(targetActor.items || []);

    for (const key of [
      "H0D_Defense_Totale_Calc",
      "H0D_Defense_Totale",
      "H0D_Creature_DEF_Total_Calc",
      "H0D_Machine_DEF_Total_Calc"
    ]) {
      if (h0dHas(p, key) && p[key] !== "") {
        const v = Number(p[key]);
        if (Number.isFinite(v)) return v;
      }
    }

    if (h0dHas(p, "H0D_DEX") || h0dHas(p, "H0D_Classe_Fort_Rangs")) {
      const dexMod = Math.floor((h0dNum(p.H0D_DEX) - 10) / 2);
      const fort = h0dNum(p.H0D_Classe_Fort_Rangs);
      const rapide = h0dNum(p.H0D_Classe_Rapide_Rangs);
      const robuste = h0dNum(p.H0D_Classe_Robuste_Rangs);
      const intelligent = h0dNum(p.H0D_Classe_Intelligent_Rangs);
      const devoue = h0dNum(p.H0D_Classe_Devoue_Rangs);
      const charismatique = h0dNum(p.H0D_Classe_Charismatique_Rangs);
      const prog = r => (r > 0 ? 1 : 0) + (r > 1 ? 1 : 0) + (r > 3 ? 1 : 0) + (r > 6 ? 1 : 0) + (r > 8 ? 1 : 0);
      const classDefense =
        prog(fort)
        + (rapide > 0 ? 3 + Math.floor(rapide / 2) : 0)
        + prog(robuste)
        + Math.floor((intelligent + 1) / 3)
        + prog(devoue)
        + Math.floor((charismatique + 1) / 3);
      const sizeMap = {Infime:8,Minuscule:4,TresPetite:2,Petite:1,Moyenne:0,Grande:-1,TresGrande:-2,Gigantesque:-4,Colossale:-8};
      const sizeMod = sizeMap[String(p.H0D_Taille || "Moyenne")] ?? 0;
      let armorBase = 0, equipmentTraitDef = 0, featDef = 0;

      for (const item of items) {
        const ip = item.system?.props || {};
        const stockage = String(ip.H0D_Stockage || "");
        if (stockage === "PJ" && h0dHas(ip,"H0D_Armure_Active") && h0dBool(ip.H0D_Armure_Active)) {
          armorBase += h0dNum(ip.H0D_Armure_Bonus_Defense);
          equipmentTraitDef += h0dTraitDef(ip,"H0D_Armure");
        }
        if (stockage === "PJ" && String(ip.H0D_Objet_Type || "") !== "Munition" && h0dHas(ip,"H0D_Objet_Actif") && h0dBool(ip.H0D_Objet_Actif)) {
          equipmentTraitDef += h0dTraitDef(ip,"H0D_Objet");
        }
        if (h0dHas(ip,"H0D_DT_Actif") && h0dBool(ip.H0D_DT_Actif)) {
          featDef += h0dNum(ip.H0D_DT_Bonus_DEF_Perm) + h0dNum(ip.H0D_DT_Bonus_DEF_Esquive);
        }
      }
      return 10 + dexMod + classDefense + armorBase + sizeMod + h0dNum(p.H0D_Defense_Divers) + featDef + equipmentTraitDef;
    }

    if (h0dHas(p,"H0D_Creature_DEF_Base")) {
      let armorDef=0, objectDef=0, moduleDef=0;
      for (const item of items) {
        const ip=item.system?.props || {};
        const stockage=String(ip.H0D_Stockage || "");
        if (stockage === "PJ" && h0dHas(ip,"H0D_Armure_Active") && h0dBool(ip.H0D_Armure_Active)) {
          armorDef += h0dNum(ip.H0D_Armure_Bonus_Defense) + h0dTraitDef(ip,"H0D_Armure");
        }
        if (stockage === "PJ" && String(ip.H0D_Objet_Type || "") !== "Munition" && h0dHas(ip,"H0D_Objet_Actif") && h0dBool(ip.H0D_Objet_Actif)) {
          objectDef += h0dTraitDef(ip,"H0D_Objet");
        }
        if (h0dHas(ip,"H0D_CM_Actif") && h0dBool(ip.H0D_CM_Actif)) {
          moduleDef += h0dNum(ip.H0D_CM_Bonus_DEF);
        }
      }
      return Math.max(0,h0dNum(p.H0D_Creature_DEF_Base)+h0dNum(p.H0D_Creature_DEF_Divers)+armorDef+objectDef+moduleDef);
    }

    if (h0dHas(p,"H0D_Machine_DEF_Corps_Base")) {
      let pieceDef=0;
      for (const item of items) {
        const ip=item.system?.props || {};
        if (h0dHas(ip,"H0D_Composant_Bonus_DEF_Machine")) {
          const state=String(ip.H0D_Composant_Etat || "");
          if (h0dNum(ip.H0D_Composant_PV_Actuels)>0 && state!=="Detruit" && state!=="Detache") {
            pieceDef += h0dNum(ip.H0D_Composant_Bonus_DEF_Machine);
          }
        }
      }
      return Math.max(0,h0dNum(p.H0D_Machine_DEF_Corps_Base)+pieceDef+h0dNum(p.H0D_Machine_Mod_DEF_Temp));
    }
    return null;
  }

  function h0dAttackVerdict(natural,total,defense) {
    const n=Number(natural);
    const hasDefense = defense !== null && defense !== undefined && Number.isFinite(Number(defense));
    const def = hasDefense ? Number(defense) : null;
    const margin = hasDefense ? Number(total) - def : null;

    if (n === 1) return {hit:false,text:"RATÉ — 1 naturel",margin};
    if (n === 20) return {hit:true,text:"TOUCHÉ — 20 naturel",margin};
    if (!hasDefense) return {hit:null,text:"NON COMPARÉ",margin:null};

    const hit = Number(total) >= def;
    return {hit,margin,text:hit ? "TOUCHÉ" : "RATÉ"};
  }

  const cdDuration = Math.max(0, Number(wp.H0D_ArmeMachine_Recharge || 0));
  if (mode === "Speciale" && cdDuration < 1) {
    const msg = weapon.name + " : une attaque Spéciale doit avoir un cooldown d’au moins 1 round.";
    if (ui.notifications) ui.notifications.warn(msg);
    return "<strong>ATTAQUE SPÉCIALE INVALIDE</strong><br>" + esc(msg);
  }
  let cdMode = String(wp.H0D_ArmeMachine_Cooldown_Mode || "Auto");
  let cdActive = wp.H0D_ArmeMachine_Cooldown_Actif === true || wp.H0D_ArmeMachine_Cooldown_Actif === "true";
  let cdElapsed = Math.max(0, Number(wp.H0D_ArmeMachine_Recharge_Compteur || 0));
  const cdCombat = game.combat || null;

  if (cdDuration > 0 && cdActive) {
    if (cdMode === "Auto") {
      const sameCombat = cdCombat
        && Number(cdCombat.round || 0) > 0
        && String(wp.H0D_ArmeMachine_Cooldown_CombatId || "") === String(cdCombat.id || "")
        && Number(wp.H0D_ArmeMachine_Cooldown_DebutRound || 0) > 0;

      if (sameCombat) {
        cdElapsed = Math.max(0, Number(cdCombat.round || 0) - Number(wp.H0D_ArmeMachine_Cooldown_DebutRound || 0));

        if (cdElapsed >= cdDuration) {
          cdActive = false;
          await weapon.update({
            "system.props.H0D_ArmeMachine_Cooldown_Actif": false,
            "system.props.H0D_ArmeMachine_Recharge_Compteur": cdDuration
          });
        } else {
          if (cdElapsed !== Number(wp.H0D_ArmeMachine_Recharge_Compteur || 0)) {
            await weapon.update({"system.props.H0D_ArmeMachine_Recharge_Compteur": cdElapsed});
          }
          return "<strong>RECHARGE EN COURS — " + weapon.name + "</strong><br>"
            + "Mode : automatique (Combat Tracker)<br>"
            + "Rounds écoulés : " + cdElapsed + " / " + cdDuration + "<br>"
            + "Disponible au round " + (Number(wp.H0D_ArmeMachine_Cooldown_DebutRound || 0) + cdDuration) + ".";
        }
      } else {
        cdActive = false;
        await weapon.update({
          "system.props.H0D_ArmeMachine_Cooldown_Actif": false,
          "system.props.H0D_ArmeMachine_Recharge_Compteur": cdDuration,
          "system.props.H0D_ArmeMachine_Cooldown_CombatId": "",
          "system.props.H0D_ArmeMachine_Cooldown_DebutRound": 0
        });
      }
    } else {
      if (cdElapsed < cdDuration) {
        return "<strong>RECHARGE EN COURS — " + weapon.name + "</strong><br>"
          + "Mode : manuel<br>"
          + "Rounds écoulés : " + cdElapsed + " / " + cdDuration + ".";
      }

      cdActive = false;
      await weapon.update({"system.props.H0D_ArmeMachine_Cooldown_Actif": false});
    }
  }

  let targetName = "Aucune cible";
  let softWarning = "";
  if (h0dTargets.length === 1) {
    const t = h0dTargets[0];
    targetName = t.name || t.actor?.name || "Cible";
  } else if (h0dTargets.length > 1) {
    targetName = "Plusieurs cibles (" + h0dTargets.length + ")";
    softWarning = "Plusieurs cibles : DEF et portée non comparées ; jet effectué sans malus de portée.";
  }

  let rangePenalty = 0;
  let measuredDistance = null;
  let rangeBand = null;
  let rangeUnits = "";
  let rangeInfo = "Non mesurée";

  const rawRange = String(wp.H0D_ArmeMachine_Portee || "0").replace(",", ".");
  const rangeMatch = rawRange.match(/-?\d+(?:\.\d+)?/);
  const rangeValue = rangeMatch ? Number(rangeMatch[0]) : 0;

  const isDistance = mode === "Distance";
  const isLimitedSpecial = (mode === "Zone" || mode === "Speciale") && rangeValue > 0;

  if (isDistance || isLimitedSpecial) {
    // Ciblage soft : l'absence de cible/token/canvas n'empêche pas le jet.
    if (h0dTargets.length !== 1) {
      if (!softWarning) {
        softWarning = "Aucune cible : DEF et portée non comparées ; jet effectué sans malus de portée.";
      }
      if (ui.notifications) ui.notifications.warn(softWarning);
    } else if (!(rangeValue > 0)) {
      softWarning = weapon.name + " : portée invalide ; jet effectué sans calcul de portée.";
      if (ui.notifications) ui.notifications.warn(softWarning);
    } else if (!canvas?.ready || !canvas.grid || !canvas.tokens) {
      softWarning = "Canvas indisponible : jet effectué sans calcul de portée.";
      if (ui.notifications) ui.notifications.warn(softWarning);
    } else {
      const shooters = (canvas.tokens.controlled || []).filter(function(t) {
        return t.actor === actor || t.document?.actorId === actor?.id;
      });

      if (shooters.length !== 1) {
        softWarning = shooters.length === 0
          ? "Sélectionnez le token de la machine pour calculer la portée. Jet effectué sans calcul de portée."
          : "Plusieurs tokens de cette machine sont sélectionnés. Jet effectué sans calcul de portée.";
        if (ui.notifications) ui.notifications.warn(softWarning);
      } else {
        const shooter = shooters[0];
        const target = h0dTargets[0];
        targetName = target.name || target.actor?.name || "Cible";

        const measurement = canvas.grid.measurePath([
          {x: shooter.center.x, y: shooter.center.y},
          {x: target.center.x, y: target.center.y}
        ]);

        measuredDistance = Number(measurement?.distance ?? 0);
        rangeUnits = String(canvas.scene?.grid?.units || canvas.dimensions?.units || "").trim();

        const epsilon = 1e-6;

        if (isDistance) {
          rangeBand = Math.max(1, Math.ceil((measuredDistance - epsilon) / rangeValue));
          const maxBands = 10;

          if (measuredDistance > (rangeValue * maxBands) + epsilon) {
            const msg = weapon.name + " : cible hors portée maximale ("
              + measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "")
              + " / " + (rangeValue * maxBands)
              + (rangeUnits ? " " + rangeUnits : "") + ").";
            if (ui.notifications) ui.notifications.warn(msg);
            return "<strong>CIBLE HORS PORTÉE</strong><br>" + esc(msg);
          }

          rangePenalty = -2 * Math.max(0, rangeBand - 1);
          rangeInfo = "Intervalle " + rangeBand + "/10 · malus "
            + (rangePenalty >= 0 ? "+" : "") + rangePenalty;
        } else {
          if (measuredDistance > rangeValue + epsilon) {
            const msg = weapon.name + " : cible hors portée maximale ("
              + measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "")
              + " / " + rangeValue + (rangeUnits ? " " + rangeUnits : "") + ").";
            if (ui.notifications) ui.notifications.warn(msg);
            return "<strong>CIBLE HORS PORTÉE</strong><br>" + esc(msg);
          }
          rangeInfo = "Dans la portée maximale · aucun malus d'intervalle";
        }
      }
    }
  }

  const situationalMod = Number("${H0D_Attaque_Mod_Situ}$") || 0;
  const natural = Number(localVars.H0D_Machine_ATK_ROLL || 0);
  const bonus = Number(localVars.H0D_Machine_ATK_TMP || 0);
  const total = natural + bonus + rangePenalty + situationalMod;
  const defenseToken = h0dTargets.length === 1 ? h0dTargets[0] : null;
  const targetDefense = defenseToken?.actor ? h0dResolveDefense(defenseToken.actor) : null;
  const attackVerdict = h0dAttackVerdict(natural, total, targetDefense);
  const publicMarginText = "";
  const defenseRow = "";
  if (targetDefense !== null) {
    try {
      const gmIds = ChatMessage.getWhisperRecipients("GM").map(u => u.id);
      if (gmIds.length) {
        const gmMargin = attackVerdict.margin === null ? "—" : ((attackVerdict.margin >= 0 ? "+" : "") + attackVerdict.margin);
        await ChatMessage.create({
          speaker: ChatMessage.getSpeaker({actor}),
          whisper: gmIds,
          content: "<div><strong>MJ — " + esc(String(wp.H0D_ArmeMachine_Type || weapon.name)) + "</strong> · "
            + esc(targetName) + " · DEF <strong>" + targetDefense + "</strong> · marge <strong>" + gmMargin
            + "</strong> · " + attackVerdict.text + "</div>"
        });
      }
    } catch (gmErr) {
      console.warn("H0D — détail DEF MJ non envoyé", gmErr);
    }
  }
  const warningBox = softWarning
    ? "<div class=\"h0d-chat-warning\"><strong>Avertissement :</strong> <em>" + esc(softWarning) + "</em></div>"
    : "";

  let cooldownAfterText = "";
  if (cdDuration > 0) {
    const liveCombat = game.combat || null;
    const liveRound = Number(liveCombat?.round || 0);

    if (cdMode === "Auto" && liveCombat && liveRound > 0) {
      await weapon.update({
        "system.props.H0D_ArmeMachine_Cooldown_Mode": "Auto",
        "system.props.H0D_ArmeMachine_Cooldown_Actif": true,
        "system.props.H0D_ArmeMachine_Cooldown_CombatId": String(liveCombat.id || ""),
        "system.props.H0D_ArmeMachine_Cooldown_DebutRound": liveRound,
        "system.props.H0D_ArmeMachine_Recharge_Compteur": 0
      });
      cooldownAfterText = "AUTO — 0/" + cdDuration + " (prêt au round " + (liveRound + cdDuration) + ")";
    } else {
      cdMode = "Manuel";
      await weapon.update({
        "system.props.H0D_ArmeMachine_Cooldown_Mode": "Manuel",
        "system.props.H0D_ArmeMachine_Cooldown_Actif": true,
        "system.props.H0D_ArmeMachine_Cooldown_CombatId": "",
        "system.props.H0D_ArmeMachine_Cooldown_DebutRound": 0,
        "system.props.H0D_ArmeMachine_Recharge_Compteur": 0
      });
      cooldownAfterText = "MANUEL — 0/" + cdDuration;
    }
  }

  let rangeRows = "";
  if (measuredDistance !== null) {
    const distText = measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "");
    rangeRows =
      "<tr><td>Distance</td><td>" + esc(distText) + "</td></tr>"
      + "<tr><td>Portée auto</td><td>" + esc(rangeInfo) + "</td></tr>";
  }

    const h0dRawDamageFormula = String(wp.H0D_ArmeMachine_Degats || "0").trim() || "0";
  const h0dDamageType = String(wp.H0D_ArmeMachine_Type_Degats || "").trim();
  let h0dDamageTotal = null;
  let h0dDamageError = "";

  try {
    const h0dDamageRoll = await (new foundry.dice.Roll(h0dRawDamageFormula)).evaluate();
    h0dDamageTotal = Number(h0dDamageRoll.total || 0);
  } catch (dmgErr) {
    h0dDamageError = String(dmgErr?.message || dmgErr || "");
    console.warn("H0D — dégâts Machine non lançables :", h0dRawDamageFormula, dmgErr);
  }

  const h0dDamageValue = h0dDamageTotal === null
    ? h0dRawDamageFormula
    : String(h0dDamageTotal);

  const h0dDamageDisplay = h0dDamageType && h0dDamageType !== "—"
    ? h0dDamageValue + " — " + h0dDamageType
    : h0dDamageValue;

  function h0dSign(v) {
    const n = Number(v) || 0;
    return (n >= 0 ? "+" : "") + n;
  }
  function h0dDetailRow(label, value, strong=false) {
    return "<tr><td>" + esc(label) + "</td><td style=\"text-align:right;\">"
      + (strong ? "<strong>" : "") + esc(value) + (strong ? "</strong>" : "") + "</td></tr>";
  }

  const totalAttackBonus = total - natural;
  let compactDetails = "";
  compactDetails += h0dDetailRow("d20", natural, true);
  compactDetails += h0dDetailRow("Bonus attaque", h0dSign(bonus));
  if (rangePenalty !== 0) {
    const rangeContext = measuredDistance !== null
      ? (measuredDistance.toFixed(1) + (rangeUnits ? " " + rangeUnits : "") + " · " + h0dSign(rangePenalty))
      : h0dSign(rangePenalty);
    compactDetails += h0dDetailRow("Portée", rangeContext);
  }
  if (situationalMod !== 0) compactDetails += h0dDetailRow("Situationnel", h0dSign(situationalMod));
  compactDetails += h0dDetailRow("Bonus total", h0dSign(totalAttackBonus), true);
  if (h0dDamageTotal !== null) compactDetails += h0dDetailRow("Formule dégâts", h0dRawDamageFormula);
  else if (h0dDamageError) compactDetails += h0dDetailRow("Dégâts", h0dRawDamageFormula);

  let compactMeta = "";
  const element = String(wp.H0D_ArmeMachine_Element || "");
  if (element && element !== "Aucun" && element !== "—") compactMeta += "<span>Élément : <b>" + esc(element) + "</b></span>";
  if (cooldownAfterText) compactMeta += "<span>Recharge : <b>" + esc(cooldownAfterText) + "</b></span>";

  const h0dEffectText = String(wp.H0D_ArmeMachine_Effet_Special || "").trim();
  const h0dEffectRow = h0dEffectText
    ? "<tr><td>Effet</td><td><strong>" + esc(h0dEffectText) + "</strong></td></tr>"
    : "";

  return "<div class=\"h0d-chat-card h0d-chat-attack h0d-chat-machine\">"
    + "<div class=\"h0d-chat-headline\">" + esc(weapon.name) + "</div>"
    + warningBox
    + "<table class=\"h0d-chat-summary\">"
    + "<tr><td><strong>Résultat</strong></td><td><strong>" + total + "</strong></td></tr>"
    + "<tr><td><strong>Verdict</strong></td><td><strong>" + attackVerdict.text + publicMarginText + "</strong></td></tr>"
    + "<tr><td>Cible</td><td><strong>" + esc(targetName) + "</strong></td></tr>"
    + defenseRow
    + "<tr><td>Dégâts</td><td><strong>" + esc(h0dDamageDisplay) + "</strong></td></tr>"
    + h0dEffectRow
    + "</table>"
    + (compactMeta ? "<div class=\"h0d-chat-meta\">" + compactMeta + "</div>" : "")
    + "<details><summary>Détails du jet</summary><table>" + compactDetails + "</table></details>"
    + "</div>";

} catch (err) {
  console.error("H0D — erreur attaque Machine", err);
  if (ui.notifications) ui.notifications.error("H0D — attaque Machine : " + (err?.message || err));
  return "<strong>ERREUR ATTAQUE MACHINE</strong><br>" + (err?.message || String(err));
}
}%

%{
const weapon = linkedEntity;
if (!weapon) return "<strong>Arme introuvable.</strong>";

const p = weapon.system && weapon.system.props ? weapon.system.props : {};
const duration = Math.max(0, Number(p.H0D_ArmeMachine_Recharge || 0));
if (duration <= 0) return "<strong>" + weapon.name + "</strong> : aucun cooldown.";

let mode = String(p.H0D_ArmeMachine_Cooldown_Mode || "Auto");
let active = p.H0D_ArmeMachine_Cooldown_Actif === true || p.H0D_ArmeMachine_Cooldown_Actif === "true";
let elapsed = Math.max(0, Number(p.H0D_ArmeMachine_Recharge_Compteur || 0));
const combat = game.combat || null;
const round = Number(combat?.round || 0);

if (active && mode === "Auto") {
  const sameCombat = combat
    && round > 0
    && String(p.H0D_ArmeMachine_Cooldown_CombatId || "") === String(combat.id || "")
    && Number(p.H0D_ArmeMachine_Cooldown_DebutRound || 0) > 0;

  if (sameCombat) {
    elapsed = Math.max(0, round - Number(p.H0D_ArmeMachine_Cooldown_DebutRound || 0));
    if (elapsed >= duration) active = false;
  } else {
    active = false;
    elapsed = duration;
  }
}

const selectedAuto = mode === "Manuel" ? "" : " selected";
const selectedManual = mode === "Manuel" ? " selected" : "";
const selectedActive = active ? " selected" : "";
const selectedReady = active ? "" : " selected";

const fd = await foundry.applications.api.DialogV2.input({
  window: {title: "Cooldown — " + weapon.name},
  content:
    "<div class=\"form-group\"><label>Mode</label>"
    + "<select name=\"mode\">"
    + "<option value=\"Auto\"" + selectedAuto + ">Automatique — Combat Tracker</option>"
    + "<option value=\"Manuel\"" + selectedManual + ">Manuel</option>"
    + "</select></div>"
    + "<div class=\"form-group\"><label>État</label>"
    + "<select name=\"state\">"
    + "<option value=\"active\"" + selectedActive + ">En recharge</option>"
    + "<option value=\"ready\"" + selectedReady + ">Prêt</option>"
    + "</select></div>"
    + "<div class=\"form-group\"><label>Rounds écoulés</label>"
    + "<input name=\"elapsed\" type=\"number\" min=\"0\" max=\"" + duration
    + "\" step=\"1\" value=\"" + Math.min(duration, elapsed) + "\"></div>"
    + "<p><strong>Durée :</strong> " + duration + " round(s).</p>",
  ok: {label: "Appliquer"},
  rejectClose: false,
  modal: true
});

if (!fd) return "<strong>" + weapon.name + "</strong> : cooldown inchangé.";

let newMode = String(fd.mode || mode);
let newActive = String(fd.state || "ready") === "active";
let newElapsed = Math.max(0, Math.min(duration, Number(fd.elapsed || 0)));

if (newElapsed >= duration) newActive = false;

const update = {
  "system.props.H0D_ArmeMachine_Cooldown_Mode": newMode,
  "system.props.H0D_ArmeMachine_Cooldown_Actif": newActive,
  "system.props.H0D_ArmeMachine_Recharge_Compteur": newActive ? newElapsed : duration
};

if (newMode === "Auto" && newActive) {
  if (combat && round > 0) {
    update["system.props.H0D_ArmeMachine_Cooldown_CombatId"] = String(combat.id || "");
    update["system.props.H0D_ArmeMachine_Cooldown_DebutRound"] = Math.max(1, round - newElapsed);
  } else {
    newMode = "Manuel";
    update["system.props.H0D_ArmeMachine_Cooldown_Mode"] = "Manuel";
    update["system.props.H0D_ArmeMachine_Cooldown_CombatId"] = "";
    update["system.props.H0D_ArmeMachine_Cooldown_DebutRound"] = 0;
    if (ui.notifications) ui.notifications.warn("H0D : aucun combat actif, passage du cooldown en mode manuel.");
  }
} else {
  update["system.props.H0D_ArmeMachine_Cooldown_CombatId"] = "";
  update["system.props.H0D_ArmeMachine_Cooldown_DebutRound"] = 0;
}

await weapon.update(update);

return "<strong>" + weapon.name + "</strong><br>"
  + "Mode : " + newMode + "<br>"
  + "État : " + (newActive ? "en recharge" : "prêt") + "<br>"
  + "Rounds écoulés : " + (newActive ? newElapsed : duration) + " / " + duration + ".";
}%

%{
const part = linkedEntity;
if (!part) {
  if (ui.notifications) ui.notifications.warn("H0D : pièce introuvable.");
  return "";
}
if (!game.user?.isGM) {
  if (ui.notifications) ui.notifications.warn("H0D : la modification des PV de pièce est réservée au MJ.");
  return "";
}

const p = part.system?.props || {};
let currentKey = "";
let maxKey = "";

if (Object.prototype.hasOwnProperty.call(p, "H0D_Composant_PV_Actuels")) {
  currentKey = "H0D_Composant_PV_Actuels";
  maxKey = "H0D_Composant_PV_Max";
} else if (Object.prototype.hasOwnProperty.call(p, "H0D_ArmeMachine_PV_Actuels")) {
  currentKey = "H0D_ArmeMachine_PV_Actuels";
  maxKey = "H0D_ArmeMachine_PV_Max";
} else {
  if (ui.notifications) ui.notifications.warn("H0D : cette ligne ne possède pas de PV éditables.");
  return "";
}

const cur = Math.max(0, Number(p[currentKey] || 0));
const maxPv = Math.max(0, Number(p[maxKey] || 0));

const fd = await foundry.applications.api.DialogV2.input({
  window: {title: "PV — " + part.name},
  content:
    "<div class=\"form-group\"><label>PV actuels</label>"
    + "<input name=\"current\" type=\"number\" min=\"0\" step=\"1\" value=\"" + cur + "\"></div>"
    + "<div class=\"form-group\"><label>PV max</label>"
    + "<input name=\"max\" type=\"number\" min=\"0\" step=\"1\" value=\"" + maxPv + "\"></div>"
    + "<p style=\"margin-top:8px\"><em>0 PV neutralise la pièce ; détachement ou destruction selon les dégâts du coup et le seuil critique 200 %.</em></p>",
  ok: {label: "Appliquer"},
  rejectClose: false,
  modal: true
});

if (!fd) return "";

const newMax = Math.max(0, Math.floor(Number(fd.max ?? maxPv) || 0));
const newCurrent = Math.max(0, Math.min(newMax, Math.floor(Number(fd.current ?? cur) || 0)));

await part.update({
  ["system.props." + maxKey]: newMax,
  ["system.props." + currentKey]: newCurrent
});

if (ui.notifications) {
  ui.notifications.info("H0D : " + part.name + " — PV " + newCurrent + " / " + newMax);
}
return "";
}%
